-- 112 Haunted Manor: the walker crosses the manor room by room. Only the
-- room it is in and one either side exist: each is a scene of its own
-- (scenes/manor/), streamed in ahead (Scene.load_additive) and dropped
-- behind (Scene.unload) - with its lights, its ghosts and a `post_volume`
-- that turns the grade as the walker comes in. Entering a room crossfades
-- the music to that room's. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/112-haunted-manor.scene"
local W = 1280.0
local ROOMS = 4
local NAMES = { "The Entrance Hall", "The Library", "The Ballroom", "The Chapel" }
local MUSIC = { "sounds/manor_hall.wav", "sounds/manor_library.wav", "sounds/manor_ballroom.wav", "sounds/manor_chapel.wav" }
local captions = true
local walker, camera, status, torch
local x, t = 0, 0
local loaded = {}
local playing = -1

local function room(k)
    return "scenes/manor/room_" .. (k % ROOMS) .. ".scene"
end

function init(entity)
    walker = Entity.find_by_name("Walker")
    camera = Entity.find_by_name("Camera")
    status = Entity.find_by_name("Status")
    torch = Entity.find_by_name("Torch")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local speed = Input.is_key_pressed("Space") and 520 or 150
    t = t + dt
    x = x + speed * dt
    local bob = math.abs(math.sin(t * speed * 0.045)) * 6
    Transform.set_position(walker, x, -240 + bob)
    Transform.set_position(camera, x + 160, 0)
    Lighting.set_intensity(torch, 1.7 + 0.25 * math.sin(t * 11.3) + 0.12 * math.sin(t * 17.9))
    -- The room the walker is in, and one either side.
    local r = math.floor((x + W / 2) / W)
    for k = math.max(0, r - 1), r + 1 do
        if not loaded[k] then loaded[k] = Scene.load_additive(room(k), k * W, 0) end
    end
    for k, h in pairs(loaded) do
        if k < r - 1 or k > r + 1 then
            Scene.unload(h)
            loaded[k] = nil
        end
    end
    -- Each room its own music, crossfaded on the way in.
    local here = r % ROOMS
    if here ~= playing then
        playing = here
        Audio.crossfade_music(MUSIC[here + 1], 2.5, 0.7, true)
    end
    UI.set_text(status, NAMES[here + 1])
end
